export interface PageLoaderWordmarkProps extends Omit<React.SVGProps<SVGSVGElement>, 'ref'> {
  /**
   * Height in pixels. Use the icon's size: the wordmark lines up with the mark the way it
   * does in the logo.
   * @default 48
   */
  size?: number;
}

/**
 * The "Oxygen UI" wordmark from the Oxygen UI logo. Uses `currentColor`.
 */
const PageLoaderWordmark: React.FC<PageLoaderWordmarkProps> = ({ size = 48, ...rest }) => (
  <svg
    xmlns="http://www.w3.org/2000/svg"
    viewBox={`0 0 ${WIDTH} ${HEIGHT}`}
    height={size}
    width={(size * WIDTH) / HEIGHT}
    role="img"
    aria-label="Oxygen UI"
    {...rest}
  >
    <path fill="currentColor" d={PATH} />
  </svg>
);

export default PageLoaderWordmark;
